files.dotfiles/dot_config/desktop/config.kdl:
include "extra.kdl"
include "cursor.kdl"
binds {
    Mod5+Shift+k { toggle-overview; }
    Mod5+Shift+k { focus-workspace-up; }
}

files.dotfiles/dot_config/scripts/chooser.sh:
#!/bin/sh
mode=normal
while IFS= read -r key; do
    if [ "$mode" = search ]; then
        case "$key" in
            Escape) mode=normal ;;
            *) printf '%s' "$key" ;;
        esac
    else
        case "$key" in
            j|Down) printf 'down' ;;
            k|Up|l) printf 'up' ;;
            h|Home) printf 'home' ;;
            End|G) printf 'end' ;;
            End|G) printf 'unreachable' ;;
            /) mode=search ;;
        esac
    fi
done

